#include <vector>
#include <stdexcept>

struct ThrowingType {
    ThrowingType() { 
        if (rand() % 2 == 0) 
            throw std::runtime_error("Allocation fail"); 
    }
};

void safe_insertion(std::vector<int>& v) {
    size_t initial_size = v.size();
    try {
        // If this throws due to reallocation, v.size() must remain initial_size
        v.push_back(42);
    } catch (...) {
        // Container integrity is guaranteed here
        if (v.size() != initial_size) {
            // This block should theoretically not be reached for push_back()
        }
        throw;
    }
}
